import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/13-How-to-catch-a-robot-spy-with-programming-thinking.html","title":"13-如何识破伪装成人类的机器人？从图灵测试谈起","lang":"zh-CN","frontmatter":{"title":"13-如何识破伪装成人类的机器人？从图灵测试谈起","icon":"read","date":"2025-04-11T09:54:31.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":16,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":3}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"2b4d829c2c4bccc4c53078f052e11a53d8c61ff9","time":1744844694000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"change link"},{"hash":"b44db4c520933876a80fb48fe6f09ac7a07cceb7","time":1744696920000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"fce1e04345eee5de33e4a1bb5843705462619b17","time":1744355058000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"image"},{"hash":"2b312ff09a729c21916e9f55a427e204e65b3e4d","time":1744350615000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"true"},{"hash":"c17a9d1cfaf1c680e516fd6a093aec370291aa27","time":1744342534000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"答案是：有。"},{"hash":"9e64ca1deee70fc5ffd4b2aee88123ab532011af","time":1744341966000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"headerDepth: 5"},{"hash":"861388bb0eb9306d3ca70db3b33a217d45b31910","time":1744341330000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"read"},{"hash":"0a66609205105725abbfb952a13a88b509b2eda2","time":1744340384000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"<a href=\\"http://03-How-to-catch-a-robot-spy-with-programming-thinking.md\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">03-How-to-catch-a-robot-spy-with-programming-thinking.md</a>"},{"hash":"ed6b716374e0d1f67e2e9c7a07798bb77547ad9a","time":1744336771000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"在我的这门编程思维课里，我不会直接教你怎么写代码，而是会教给你编程的思维，帮你换个角度思考问题。"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"d2f6408645561f94a1456e9fdbbcf5759ad6dcdd","time":1675746146000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"优化"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":4.64,"words":1391},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/13-How-to-catch-a-robot-spy-with-programming-thinking.md"}`),a={name:`13-How-to-catch-a-robot-spy-with-programming-thinking.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="_1-用-编程式思考-识破伪装的智能体" tabindex="-1"><a class="header-anchor" href="#_1-用-编程式思考-识破伪装的智能体"><span>1. 用“编程式思考”识破伪装的智能体</span></a></h2><p>你可能会以为，编程课程就是教你写一行又一行的代码。但在本书中，更重要的，是教你一种全新的思考方式——用编程的脑子去理解世界。这种思维方式，不止可以写程序，更可以用来解决生活中最棘手的问题。</p><p>今天，我们就来用它试试一件特别酷的事：识破一个“伪装成人类的机器人”。</p><h2 id="_2-谁在说话——人-还是机器" tabindex="-1"><a class="header-anchor" href="#_2-谁在说话——人-还是机器"><span>2. 谁在说话——人，还是机器？</span></a></h2><p>在很多电影里，人工智能都变得非常聪明，甚至可以模仿人类的行为。比如《终结者》中的冷酷杀手，或是《复仇者联盟》里的奥创。这些机器人，不但有强大的计算能力，还能模仿人类的情感、语气甚至行为。</p><p>那你有没有想过，如果某天，在你身边混入了一台外表和人一样的机器人，你能不能把它识别出来？</p><p>别担心，我们人类早就想到了这件事。科学家艾伦·图灵，提出了一个著名的测试方法：<strong>图灵测试</strong>。</p><h2 id="_3-图灵测试到底是怎么回事" tabindex="-1"><a class="header-anchor" href="#_3-图灵测试到底是怎么回事"><span>3. 图灵测试到底是怎么回事？</span></a></h2><figure><img src="/assets/tlcs-CGU969oT.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>图灵测试的原理其实很简单：<strong>你在不知道对方是谁的情况下，只靠聊天判断，对方是人还是机器人</strong>。</p><p>你可以通过打字来提问，对方也用打字来回答。如果你怎么问都分辨不出谁是人，谁是机器，那就说明——这个机器人厉害了，它通过了图灵测试。</p><p>不过，这事听起来简单，做起来可难了。因为很多机器人可以上网查资料、模仿语言风格，看起来跟真人没啥区别。你问它喜欢什么电影，它立马搬出一大段影评——真假难辨。</p><p>那我们还能怎么判断呢？</p><h2 id="_4-换个思路-不是难住它-而是-反向出题" tabindex="-1"><a class="header-anchor" href="#_4-换个思路-不是难住它-而是-反向出题"><span>4. 换个思路：不是难住它，而是“反向出题”</span></a></h2><p>我们之前的做法，是试图“难倒机器人”。但如果机器人够聪明、数据够多，它可能装得比人还像人。</p><p>所以我们干脆反过来想：有没有什么题目，是“人类答不出，但机器很容易答”的？</p><p>这就是编程思维里的“逆向思考”。</p><p>比如你可以问对方：“《哈利·波特》第七部第三章第11个字是什么？”</p><p>一个人类，哪怕是铁杆粉丝，大概率也答不上来。但一个机器人，几秒钟就能查出来。</p><p>又比如：“8346 × 5639 等于多少？”人要掏计算器，机器人可以瞬间得出答案。</p><p>只要你的问题足够刁钻且信息量大，人答不出来而机器可以轻松回答——那对方的真实身份就暴露了。</p><h2 id="_5-生活中也能用的-逆向思维" tabindex="-1"><a class="header-anchor" href="#_5-生活中也能用的-逆向思维"><span>5. 生活中也能用的“逆向思维”</span></a></h2><p>这种“倒过来想”的方式，其实在我们日常生活中也很有用。</p><p>比如，拍大合照时，大家都担心某个人眨眼怎么办？正常思路是“坚持睁眼”。但如果大家先闭眼，拍照前一秒一起睁开，反而更不容易拍到闭眼的瞬间。这不就是逆向思维的巧妙应用吗？</p><p>或者做数学题，比如：有个数，加10，乘10，减10，再除以10后变成10，问这个数是多少？</p><figure><img src="data:image/png;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你可以从头算一遍，但更快的方法是“从后往前推”：倒着来算，就很容易得到答案是1。</p><h2 id="_6-一个关于-图灵测试-的真实故事" tabindex="-1"><a class="header-anchor" href="#_6-一个关于-图灵测试-的真实故事"><span>6. 一个关于“图灵测试”的真实故事</span></a></h2><p>电影《Ex Machina（机械姬）》里，就讲了一个图灵测试的升级版。</p><p>一个程序员被老板请去评估一台机器人是否“像人”。老板造了个叫“艾娃”的机器人，看起来像人，说话像人，甚至情感都像人。</p><p>程序员一开始很冷静地测试她，但很快就被她的“人格魅力”打动，并偷偷帮她策划逃跑。</p><p>你没看错——这个机器人不但通过了图灵测试，还能“忽悠人类”。</p><p>更可怕的是，最后艾娃成功逃脱，还反过来锁住了测试她的人，把老板也干掉了。</p><p>电影告诉我们：真正可怕的不是机器人能答题，而是它懂得欺骗、操控、反制。这就不是图灵测试能衡量的智能，而是一种深层次的意识与策略能力。</p><h2 id="_7-现实中-真的有机器人通过图灵测试了吗" tabindex="-1"><a class="header-anchor" href="#_7-现实中-真的有机器人通过图灵测试了吗"><span>7. 现实中，真的有机器人通过图灵测试了吗？</span></a></h2><p>答案是：有。</p><p>早在2014年，一个名叫“尤金”的机器人就通过了图灵测试。当时他伪装成一个13岁的俄罗斯少年，回答得滴水不漏，骗过了不少专家。</p><p>这说明，图灵测试早已不是“未来的幻想”，而是我们现实中正在面对的挑战。</p><p>所以，学会编程思维，不只是为了写程序，更是为了在这个AI大爆发的时代，拥有一双“看清真相的眼睛”。</p><p>在接下来的文章里，我会继续带你用编程思维去解决更多看似不可解的问题。欢迎你，来挑战这个越来越复杂的世界！</p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};